import { Criterion, Alternative } from "./topsis";

export interface LaptopRecord {
  id: string;
  company: string;
  product: string;
  typeName: string;
  inches: number;
  ram: number;
  os: string;
  weight: number;
  priceEuros: number;
  screen: string;
  screenW: number;
  screenH: number;
  touchscreen: boolean;
  ipsPanel: boolean;
  retinaDisplay: boolean;
  cpuCompany: string;
  cpuFreq: number;
  cpuModel: string;
  primaryStorage: number;
  secondaryStorage: number;
  primaryStorageType: string;
  secondaryStorageType: string;
  gpuCompany: string;
  gpuModel: string;
}

export const LAPTOP_CSV_CRITERIA: Criterion[] = [
  { id: "C1", name: "Harga (Euro €)", weight: 0.25, point: 25, type: "cost" },
  { id: "C2", name: "Kapasitas RAM (GB)", weight: 0.20, point: 20, type: "benefit" },
  { id: "C3", name: "Frekuensi CPU (GHz)", weight: 0.20, point: 20, type: "benefit" },
  { id: "C4", name: "Total Storage (GB)", weight: 0.15, point: 15, type: "benefit" },
  { id: "C5", name: "Resolusi Layar (MP)", weight: 0.10, point: 10, type: "benefit" },
  { id: "C6", name: "Berat Fisik (Kg)", weight: 0.10, point: 10, type: "cost" }
];

export function laptopToAlternative(item: LaptopRecord, index: number): Alternative {
  const totalStorage = item.primaryStorage + item.secondaryStorage;
  const megapixels = Number(((item.screenW * item.screenH) / 1000000).toFixed(2));
  return {
    id: `A${index + 1}`,
    name: `${item.company} ${item.product} (${item.cpuModel}, ${item.ram}GB)`,
    values: [
      item.priceEuros,
      item.ram,
      item.cpuFreq,
      totalStorage,
      megapixels,
      item.weight
    ]
  };
}

